// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.deal(address(c), amount);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(!success || address(c).balance == amount);
    }
}
